from pathlib import Path
import base64, hashlib, html, json
from content import SECTIONS, SOURCES, LIMITS

ROOT = Path(__file__).resolve().parent
esc = html.escape
shots = [json.loads(s) for s in (ROOT/'evidence/screens.jsonl').read_text().splitlines()]
byid = {s['id']:s for s in shots}
source_ids = {s[0] for s in SOURCES}
count = sum(len(s[5]) for s in SECTIONS)

def refs(value):
    result=[]
    for r in value.split(','):
        if r in byid:
            result.append(f'<button class="ref" data-open="{r}" aria-label="{esc(byid[r]["title"])} 캡처 확대">화면 {r[:2]}</button>')
        elif r in source_ids:
            result.append(f'<a class="ref source-ref" href="#source-{r}">{r}</a>')
    return ' '.join(result)

def picture(sid, gallery=False):
    s=byid[sid]
    return f'''<figure class="shot {'gallery-shot' if gallery else ''}">
      <button class="image-button" data-open="{sid}" aria-label="{esc(s['title'])} 화면 확대">
       <img data-shot="{sid}" width="484" height="932" alt="{esc(s['title'])} 실제 앱 화면" loading="lazy" decoding="async">
       <span class="zoom-hint">↗ 화면 확대</span>
      </button><figcaption><span class="shot-num">{sid[:2]}</span><div><strong>{esc(s['title'])}</strong><p>{esc(s['note'])}</p></div></figcaption></figure>'''

nav = ''.join(f'<a href="#{s[0]}"><span>{i:02}</span>{esc(s[1].split(" · ")[0])}</a>' for i,s in enumerate(SECTIONS,1))
chapters=[]
inventory=[]
for si,(sid,title,kicker,intro,pics,items) in enumerate(SECTIONS,1):
    rows=[]
    for ni,(name,path,desc,status,evidence) in enumerate(items,1):
        fid=f'{sid}-f{ni:02}'
        status_class={'동작 확인':'action','화면 확인':'screen','진입점 확인':'entry','문서 보완':'docs'}[status]
        rows.append(f'''<article class="feature" id="{fid}"><div class="feature-top"><h3>{esc(name)}</h3><span class="status {status_class}">{status}</span></div>
          <p class="path">{esc(path)}</p><p>{esc(desc)}</p><div class="refs">{refs(evidence)}</div></article>''')
        inventory.append({'name':name,'path':path,'desc':desc,'status':status,'section':title,'href':'#'+fid,'evidence':evidence})
    chapters.append(f'''<section class="chapter" id="{sid}" aria-labelledby="{sid}-title"><header class="chapter-header"><p class="eyebrow">{kicker}</p><h2 id="{sid}-title">{esc(title)}</h2><p class="section-lead">{esc(intro)}</p></header>
      <div class="screens-strip">{''.join(picture(x) for x in pics)}</div><div class="features">{''.join(rows)}</div></section>''')

limits=''.join(f'<tr><th scope="row">{esc(a)}</th><td>{esc(b)}</td></tr>' for a,b in LIMITS)
sources=''.join(f'<li id="source-{i}"><span>{i}</span><div><a href="{esc(u,quote=True)}" target="_blank" rel="noopener noreferrer">{esc(t)} ↗</a><p>{esc(n)}</p></div></li>' for i,t,u,n in SOURCES)
inventory_rows=''.join(f'<tr data-status="{esc(f["status"])}"><td><a href="{f["href"]}">{esc(f["name"])}</a><small>{esc(f["section"])}</small></td><td>{esc(f["path"])}</td><td>{esc(f["desc"])}</td><td><span class="status">{esc(f["status"])}</span></td></tr>' for f in inventory)

