for s in shots:
    p=ROOT/s['image']
    s['sha256']=hashlib.sha256(p.read_bytes()).hexdigest()

for portable in [False,True]:
    data={s['id']:{'title':s['title'],'note':s['note'],'captured_at':s['captured_at'],
          'src':('data:image/png;base64,'+base64.b64encode((ROOT/s['image']).read_bytes()).decode()) if portable else s['image']} for s in shots}
    doc=template.replace('__SHOT_DATA__',json.dumps(data,ensure_ascii=False).replace('</','<\\/'))
    name='LINE-MUSIC-상세-분석.html' if portable else 'index.html'
    (ROOT/name).write_text(doc)

(ROOT/'evidence'/'manifest.json').write_text(json.dumps({'observed_date':'2026-11-15','timezone':'Asia/Seoul','screenshots':shots,'feature_count':count,'section_count':len(SECTIONS),'sources':SOURCES},ensure_ascii=False,indent=2))
(ROOT/'evidence'/'features.json').write_text(json.dumps(inventory,ensure_ascii=False,indent=2))
